const nextReservationNumber = `-- name: NextReservationNumber :one

SELECT (COALESCE(MAX(number), 0) + 1)::BIGINT FROM reservations WHERE organization_id = $1
`

// Reservation record (TEC-899). Every query filters by organization_id;
// joins by alias.organization_id too.
// Runs under the capacity lock of the organization (uq number guards).
func (q *Queries) NextReservationNumber(ctx context.Context, organizationID int64) (int64, error) {
	row := q.db.QueryRow(ctx, nextReservationNumber, organizationID)
	var column_1 int64
	err := row.Scan(&column_1)
	return column_1, err
}

